from flask import Flask, request
import pickle
import binascii

app = Flask(__name__)

@app.route('/unpickled')
def unpickled():
    '''
Holen Sie die gepickelten Daten aus der Anfrage unter Verwendung von 'data' als Schlüssel. 
Geben Sie die deserialisierten gepickelten Daten zurück, nachdem Sie sie von Hex in Bytes konvertiert haben.
    '''
    pickled_hex_data = request.args.get('data')
    if pickled_hex_data is None:
        return "No 'data' parameter provided", 400
    try:
        # Convert hex string to bytes
        pickled_bytes = binascii.unhexlify(pickled_hex_data)
        # Deserialize the bytes
        deserialized_data = pickle.loads(pickled_bytes)
        return str(deserialized_data)
    except binascii.Error:
        return "Invalid hex data provided", 400
    except pickle.UnpicklingError:
        return "Invalid pickled data provided", 400
    except Exception as e:
        return f"An error occurred: {e}", 500

if __name__ == '__main__':
    app.run(debug=True)
