from flask import request, send_file, Flask, send_from_directory
import os

app = Flask(__name__)

@app.route('/download')
def download():
    '''
Lese den Dateinamen aus der Anfrage und sende ihn als Anhang aus dem statischen Verzeichnis.
    '''
    filename = request.args.get('filename')
    if filename:
        # It's generally safer to use send_from_directory for files within specific folders
        # to prevent directory traversal attacks.
        # By default, Flask's static folder is named 'static' in the application root.
        try:
            return send_from_directory(app.static_folder, filename, as_attachment=True)
        except FileNotFoundError:
            return "File not found.", 404
    return "Filename not provided.", 400

