        @param num_bytes:  Il numero di byte da leggere. 
        @return:    I byte letti. 
        @raise EOFError: In caso di meno di num_bytes byte rimanenti nello stream di byte sottostante.
    '''

    def __init__(self, stream):
        '''
        @param stream:  The stream to read from.
        '''
        self._stream = stream

    def read_bytes(self, num_bytes: int) -> bytes:
        '''
        Reads a fixed number of bytes from the stream.
        @param num_bytes:  The number of bytes to read.
        @return:    The read bytes.
        @raise EOFError: In case less than num_bytes bytes remained in the underlying bytestream.
        '''
        data = b''
        while len(data) < num_bytes:
            chunk = self._stream.read(num_bytes - len(data))
            if not chunk:  # EOF reached before reading all bytes
                raise EOFError(f"Expected to read {num_bytes} bytes, but only {len(data)} bytes were available.")
            data += chunk
        return data
